(1, 1, 'Một người bình luận WordPress', 'wapuu@wordpress.example', 'https://vi.wordpress.org/', '', '2026-05-04 13:23:57', '2026-05-04 13:23:57', 'Xin chào, đây là một bình luận.\nĐể bắt đầu kiểm duyệt, chỉnh sửa và xóa nhận xét, vui lòng truy cập màn hình Nhận xét trong trang quản trị.\nHình đại diện của người bình luận đến từ <a href=\"https://gravatar.com/\">Gravatar</a>.', 0, '1', '', 'comment', 0, 0),
(2, 216, 'WooCommerce', '', '', '', '2026-05-04 14:19:12', '2026-05-04 14:19:12', 'Stock hold of 60 minutes applied to: <br>- Bánh Gạo Lứt Organic (ORG092) &times; 2', 0, '1', 'WooCommerce', 'order_note', 0, 0),
(3, 216, 'WooCommerce', '', '', '', '2026-05-04 14:19:12', '2026-05-04 14:19:12', 'Stock levels reduced: Bánh Gạo Lứt Organic (100&rarr;98)', 0, '1', 'WooCommerce', 'order_note', 0, 0),
