(1067, 'xoo-el-gl-options', 'a:33:{s:14:\"m-form-pattern\";s:8:\"separate\";s:13:\"m-nav-pattern\";s:4:\"tabs\";s:8:\"m-en-reg\";s:3:\"yes\";s:11:\"m-user-role\";s:8:\"customer\";s:12:\"m-auto-login\";s:3:\"yes\";s:10:\"m-reset-pw\";s:4:\"link\";s:18:\"m-reset-pw-subject\";s:36:\"Reset your password for {site_title}\";s:16:\"m-reset-pw-email\";s:728:\"<p style=\"margin: 0px 0px 16px\">Hi {user_login},</p>\r\n<p style=\"margin: 0px 0px 16px\">We received a request to reset your password for your account on <b>{site_title}</b>.</p>\r\n<p style=\"margin: 0px 0px 16px\">Your 6-digit verification code is:</p>\r\n<p style=\"font-size: 27px;font-weight: bold;background-color: #f5f5f5;text-align: center;margin: 0px 0px 16px;padding: 20px 10px\">{verify_code}</p>\r\n<p style=\"margin: 0px 0px 16px\">Enter this code on the password reset page to create a new password.</p>\r\n<p style=\"margin: 0px 0px 16px\">If you didn’t request a password reset, please ignore this email or contact our support team if you have concerns.</p>\r\n<p style=\"margin: 0px 0px 16px\">Thanks,<br />The {site_title} Team</p>\";s:11:\"popup-forms\";a:3:{i:0;s:0:\"\";i:1;s:5:\"login\";i:2;s:8:\"register\";}s:11:\"popup-force\";s:2:\"no\";s:9:\"ao-enable\";s:3:\"yes\";s:7:\"ao-once\";s:2:\"no\";s:15:\"ao-default-form\";s:5:\"login\";s:8:\"ao-pages\";s:0:\"\";s:8:\"ao-delay\";s:3:\"500\";s:11:\"m-red-login\";s:0:\"\";s:14:\"m-red-register\";s:0:\"\";s:12:\"m-red-logout\";s:12:\"/my-account/\";s:12:\"m-ep-success\";s:3:\"yes\";s:14:\"m-en-myaccount\";s:3:\"yes\";s:10:\"m-myacc-sc\";s:35:\"[xoo_el_inline_form active=\"login\"]\";s:13:\"m-myacclpw-sc\";s:36:\"[xoo_el_inline_form active=\"lostpw\"]\";s:11:\"m-en-chkout\";s:3:\"yes\";s:11:\"m-chkout-sc\";s:82:\"[xoo_el_inline_form active=\"login\" login_redirect=\"same\" register_redirect=\"same\"]\";s:13:\"txt-tab-login\";s:5:\"Login\";s:11:\"txt-tab-reg\";s:7:\"Sign Up\";s:13:\"txt-btn-login\";s:7:\"Sign in\";s:11:\"txt-btn-reg\";s:7:\"Sign Up\";s:13:\"txt-b